// Arithmetic series sum: 1 + 2 + ... + n, with n a non-negative u64 and the sum < 10_000.

fn compute_arith_sum(n: u64) -> u64 {
    // We assume S(n) < 10_000, so the result fits easily in u64.
    let mut i: u64 = 0;
    let mut sum: u64 = 0;

    while i < n {
        i += 1;
        sum += i;
    }

    sum
}

